#include "dff3d.h"

void dff3d_fprint_fixed(FILE *f, dff_fixed value)
{
    unsigned long mag;
    unsigned long whole;
    unsigned long frac;
    int neg;

    neg = 0;
    if (value < 0) {
        neg = 1;
        mag = (unsigned long)(-(value + 1));
        mag += 1UL;
    } else {
        mag = (unsigned long)value;
    }
    whole = mag >> DFF3D_FIXED_SHIFT;
    frac = ((mag & 0xffffUL) * 10000UL + 32768UL) >> DFF3D_FIXED_SHIFT;
    if (frac >= 10000UL) {
        whole++;
        frac -= 10000UL;
    }
    if (neg) {
        fputc('-', f);
    }
    fprintf(f, "%lu.%04lu", whole, frac);
}

static void dff3d_obj_index(FILE *f, unsigned long i, int has_vt, int has_vn)
{
    fprintf(f, "%lu", i);
    if (has_vt || has_vn) {
        fputc('/', f);
        if (has_vt) {
            fprintf(f, "%lu", i);
        }
        if (has_vn) {
            fputc('/', f);
            fprintf(f, "%lu", i);
        }
    }
}

int dff3d_write_obj(FILE *f, const Dff3dModel *model)
{
    dff_u32 i;
    dff_u32 g;
    const Dff3dVertex *v;
    const Dff3dTriangle *t;
    const Dff3dGeometry *geom;
    unsigned long ia;
    unsigned long ib;
    unsigned long ic;
    int has_vt;
    int has_vn;
    dff_u32 current_mat;

    if (f == DFF3D_NULL || model == DFF3D_NULL) {
        return DFF3D_ERR_NULL;
    }

    fprintf(f, "# dff3d_c89_fixed OBJ export\n");
    fprintf(f, "# vertices %lu triangles %lu geometries %lu materials %lu\n",
        (unsigned long)model->vertex_count,
        (unsigned long)model->triangle_count,
        (unsigned long)model->geometry_count,
        (unsigned long)model->material_count);
    if (model->material_count != 0U) {
        fprintf(f, "# use companion MTL generated by dff3d_write_mtl()\n");
    }

    for (i = 0U; i < model->vertex_count; ++i) {
        v = &model->vertices[i];
        fputs("v ", f);
        dff3d_fprint_fixed(f, v->pos.x);
        fputc(' ', f);
        dff3d_fprint_fixed(f, v->pos.y);
        fputc(' ', f);
        dff3d_fprint_fixed(f, v->pos.z);
        if (v->has_color) {
            fprintf(f, " # rgba %u %u %u %u", (unsigned)v->color.r, (unsigned)v->color.g, (unsigned)v->color.b, (unsigned)v->color.a);
        }
        fputc('\n', f);
    }
    for (i = 0U; i < model->vertex_count; ++i) {
        v = &model->vertices[i];
        fputs("vt ", f);
        dff3d_fprint_fixed(f, v->uv0.u);
        fputc(' ', f);
        dff3d_fprint_fixed(f, v->uv0.v);
        fputc('\n', f);
    }
    for (i = 0U; i < model->vertex_count; ++i) {
        v = &model->vertices[i];
        fputs("vn ", f);
        dff3d_fprint_fixed(f, v->normal.x);
        fputc(' ', f);
        dff3d_fprint_fixed(f, v->normal.y);
        fputc(' ', f);
        dff3d_fprint_fixed(f, v->normal.z);
        fputc('\n', f);
    }

    for (g = 0U; g < model->geometry_count; ++g) {
        geom = &model->geometries[g];
        fprintf(f, "g geometry_%lu\n", (unsigned long)g);
        has_vt = geom->uv_layers > 0U ? 1 : 0;
        has_vn = geom->has_normals != 0U ? 1 : 0;
        current_mat = 0xffffffffUL;
        for (i = 0U; i < geom->triangle_count; ++i) {
            t = &model->triangles[geom->triangle_offset + i];
            if ((dff_u32)t->material != current_mat && (dff_u32)t->material < model->material_count) {
                current_mat = (dff_u32)t->material;
                fprintf(f, "usemtl dff_mat_%lu\n", (unsigned long)current_mat);
            }
            ia = (unsigned long)geom->vertex_offset + (unsigned long)t->a + 1UL;
            ib = (unsigned long)geom->vertex_offset + (unsigned long)t->b + 1UL;
            ic = (unsigned long)geom->vertex_offset + (unsigned long)t->c + 1UL;
            fputs("f ", f);
            dff3d_obj_index(f, ia, has_vt, has_vn);
            fputc(' ', f);
            dff3d_obj_index(f, ib, has_vt, has_vn);
            fputc(' ', f);
            dff3d_obj_index(f, ic, has_vt, has_vn);
            fputc('\n', f);
        }
    }
    return DFF3D_OK;
}
